using TertiaryInstitutions.Models;

namespace TertiaryInstitutions.Data;

/// <summary>
/// University of Johannesburg undergraduate programmes, subject requirements and Total APS,
/// sourced from the Undergraduate Prospectus 2027 (NSC/IEB admission tables).
/// Where a programme's APS or subject level varies by chosen subject combination (e.g. Mathematics vs
/// Mathematical Literacy), the lower/base "with Mathematics" figure is used as the primary value and the
/// alternative is captured in Notes.
/// </summary>
public static class UJCourses
{
    private const string Eng = "English";
    private const string Math = "Mathematics";
    private const string MathLit = "Mathematical Literacy";
    private const string TechMath = "Technical Mathematics";
    private const string PhysSci = "Physical Science";
    private const string TechSci = "Technical Science";
    private const string LifeSci = "Life Science";

    private static Course C(string name, string code, string duration, string faculty, string campus, int aps, string notes, params (string Subject, string Level)[] reqs)
    {
        return new Course
        {
            Name = name,
            QualificationCode = code,
            Duration = duration,
            Faculty = faculty,
            Campus = campus,
            TotalAPS = aps,
            Notes = notes,
            SubjectRequirements = reqs.Select(r => new SubjectRequirement { Subject = r.Subject, Level = r.Level }).ToList()
        };
    }

